import re
p='src/server_runner.ts'
s=open(p).read()

old_create='''export const ExpressHttpStreamableMcpServer = (options: ServerOptions, setupCb: (server: McpServer) => void) => {
  const server = new McpServer({
    name: options.name,
    version: "1.0.0",
  }, {
    capabilities: {
      logging: {},
      tools: {
        listChanged: false
      }
    }
  });

  setupCb(server);

  const app = express();
  app.use(express.json());
'''
new_create='''export const ExpressHttpStreamableMcpServer = (options: ServerOptions, setupCb: (server: McpServer) => void) => {
  // An McpServer can only be connected to one transport at a time, so each
  // session gets its own instance. Sharing one instance across sessions routes
  // responses to whichever session connected last, hanging everyone else.
  const createServer = () => {
    const server = new McpServer({
      name: options.name,
      version: "1.0.0",
    }, {
      capabilities: {
        logging: {},
        tools: {
          listChanged: false
        }
      }
    });
    setupCb(server);
    return server;
  };

  const app = express();
  app.use(express.json());

  // Liveness endpoint for the hosting platform's health checks.
  app.get('/healthz', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });
'''
assert old_create in s; s=s.replace(old_create,new_create)

old_conn='''        // Connect to the MCP server BEFORE handling the request
        console.log(`Connecting transport to MCP server...`);
        await server.connect(transport);'''
new_conn='''        // Connect to the MCP server BEFORE handling the request
        console.log(`Connecting transport to MCP server...`);
        const server = createServer();
        await server.connect(transport);'''
assert old_conn in s; s=s.replace(old_conn,new_conn)

# Unknown session id -> 404 so clients re-initialize (MCP spec), e.g. after a restart/deploy.
old_400='''      } else {
        console.error('Invalid request: No valid session ID or initialization request');'''
new_400='''      } else if (sessionId) {
        // Per the MCP spec, an unknown/expired session gets 404 so the client
        // starts a new session (e.g. after a server restart or redeploy).
        console.error(`Unknown session ID: ${sessionId}`);
        res.status(404).json({
          jsonrpc: '2.0',
          error: {
            code: -32001,
            message: 'Session not found',
          },
          id: null,
        });
        return;
      } else {
        console.error('Invalid request: No valid session ID or initialization request');'''
assert old_400 in s; s=s.replace(old_400,new_400)

for verb in ['GET','DELETE']:
    old=f'''      if (!sessionId || !transports[sessionId]) {{
        console.log(`Invalid session ID in {verb} request: ${{sessionId}}`);
        res.status(400).send('Invalid or missing session ID');
        return;
      }}'''
    new=f'''      if (!sessionId || !transports[sessionId]) {{
        console.log(`Invalid session ID in {verb} request: ${{sessionId}}`);
        res.status(sessionId ? 404 : 400).send(sessionId ? 'Session not found' : 'Missing session ID');
        return;
      }}'''
    assert old in s, verb; s=s.replace(old,new)

old_sig='''  // Handle server shutdown
  process.on('SIGINT', async () => {
    console.log('Shutting down server...');
'''
new_sig='''  // Handle server shutdown (SIGINT locally, SIGTERM from the hosting platform)
  const shutdown = async (signal: string) => {
    console.log(`Received ${signal}, shutting down server...`);
'''
assert old_sig in s; s=s.replace(old_sig,new_sig)

old_end='''    await express_server.close();
    await server.close();
    console.log('Server shutdown complete');
    process.exit(0);
  });

  return {process, server, express_server}'''
new_end='''    express_server.close();
    console.log('Server shutdown complete');
    process.exit(0);
  };
  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));

  return {process, express_server}'''
assert old_end in s; s=s.replace(old_end,new_end)
open(p,'w').write(s)
EOF
